#include <Arduino.h>

const uint8_t TRIG = 8, ECHO = 3, LED = 9, BUTTON = 2;
const int DARK_THRESHOLD = 500;
const float NEAR_CM = 100.0f;
bool forcedOn = false;
bool lastRaw = HIGH;
bool stableButton = HIGH;
unsigned long changedAt = 0;
unsigned long lastMeasurement = 0;
bool nearPerson = false;

void updateButton() {
  bool raw = digitalRead(BUTTON);
  unsigned long now = millis();
  if (raw != lastRaw) {
    lastRaw = raw;
    changedAt = now;
  }
  if (raw != stableButton && now - changedAt >= 30) {
    stableButton = raw;
    if (stableButton == LOW) forcedOn = !forcedOn;
  }
}

void measurePresence() {
  digitalWrite(TRIG, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG, LOW);
  unsigned long duration = pulseIn(ECHO, HIGH, 30000UL);
  float cm = duration * 0.0343f / 2.0f;
  nearPerson = duration != 0 && cm < NEAR_CM;
}

void setup() {
  pinMode(TRIG, OUTPUT);
  digitalWrite(TRIG, LOW);
  pinMode(ECHO, INPUT);
  pinMode(LED, OUTPUT);
  pinMode(BUTTON, INPUT_PULLUP);
  analogWrite(LED, 0);
}

void loop() {
  updateButton();
  unsigned long now = millis();
  if (now - lastMeasurement >= 70) {
    lastMeasurement = now;
    measurePresence();
  }
  bool dark = analogRead(A0) < DARK_THRESHOLD;
  analogWrite(LED, (forcedOn || (dark && nearPerson)) ? 255 : 0);
}
